import { useState } from 'react'
import { motion } from 'framer-motion'
import { Radio, Music } from 'lucide-react'
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert'
import { AirportSelector } from './components/AirportSelector'
import { MixedAudioPlayer } from './components/MixedAudioPlayer'
import { AirportInfo } from './components/AirportInfo'
import { airports } from './data/airports'
import { Airport } from './types/airport'

function App() {
  const [selectedAirport, setSelectedAirport] = useState<Airport | null>(null)
  const [isPlaying, setIsPlaying] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleAirportSelect = (airport: Airport) => {
    setSelectedAirport(airport)
    setError(null)
    // Note: Auto-play disabled - user must click play button for both ATC and music
  }

  const handlePlayPause = (playing: boolean) => {
    setIsPlaying(playing)
  }

  const handleError = (errorMessage: string) => {
    setError(errorMessage)
    setIsPlaying(false)
  }

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="mb-12 text-center"
        >
          <div className="mb-4 flex items-center justify-center gap-3">
            <Radio className="h-8 w-8 text-primary" />
            <h1 className="text-5xl font-bold text-foreground">Live ATC Audio</h1>
            <Music className="h-8 w-8 text-primary" />
          </div>
          <p className="mx-auto max-w-2xl text-xl text-muted-foreground">
            Listen to live air traffic control communications mixed with atmospheric post-rock music
          </p>
        </motion.div>

        {/* Error Display */}
        {error && (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="mx-auto mb-6 max-w-2xl"
          >
            <Alert variant="destructive">
              <AlertTitle>Error</AlertTitle>
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          </motion.div>
        )}

        {/* Main Content */}
        <div className="space-y-8">
          {/* Airport Selection */}
          <AirportSelector
            airports={airports}
            selectedAirport={selectedAirport}
            onAirportSelect={handleAirportSelect}
          />

          {/* Mixed Audio Player */}
          <MixedAudioPlayer
            airport={selectedAirport}
            isPlaying={isPlaying}
            onPlayPause={handlePlayPause}
            onError={handleError}
          />

          {/* Airport Information */}
          <AirportInfo airport={selectedAirport} />
        </div>

        {/* Footer */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.6, delay: 0.8 }}
          className="mt-16 text-center text-muted-foreground"
        >
          <p className="text-sm">
            Audio feeds provided by{' '}
            <a
              href="https://liveatc.net"
              target="_blank"
              rel="noopener noreferrer"
              className="text-primary underline hover:text-primary/80"
            >
              LiveATC.net
            </a>
          </p>
          <p className="mt-2 text-xs">
            Live ATC audio streams provided via CORS proxy. Some streams may be temporarily unavailable.
          </p>
        </motion.div>
      </div>
    </div>
  )
}

export default App
